-- ============================================================
-- SEED EXT 4: Módulo 16 — Articles Advanced (ex 142-220)
-- Novos tópicos: articles em abstract/academic writing avançado,
-- zero article com proper nouns, articles em títulos e headlines,
-- determiners avançados (such/rather/quite a)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'articles-advanced';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo articles-advanced não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Zero article vs the — academic generic reference
  (cid,41,142,'multiple_choice','Which sentence correctly uses the ZERO ARTICLE for generic reference?','Education shapes the individual''s capacity to participate in economic and civic life.','["The education shapes an individual''s capacity to participate in economic life.","Education shapes the individual''s capacity to participate in economic and civic life.","An education shapes the individuals'' capacity to participate in economic life.","The education shapes individuals capacity to participate in economic life."]','Generic uncountable (Education) = zero article. "The individual" = generic singular with "the" for abstraction.','hard'),
  (cid,41,143,'gap_fill','_____ poverty is a global phenomenon, but _____ poverty that exists in wealthy nations is often structurally distinct from _____ extreme poverty found in low-income countries.','zero / the / the',NULL,'Generic (poverty as concept) = zero. Specific subcategories get "the."','hard'),
  (cid,41,144,'multiple_choice','Which sentence correctly uses BOTH generic zero article and specific "the" in the same sentence?','Language is the primary medium through which human thought is organized and transmitted.','["The language is the primary medium through which human thought is organized.","Language is a primary medium through which the human thought is organized.","Language is the primary medium through which human thought is organized and transmitted.","Languages are the primary medium through which human thoughts are organized."]','"Language" = zero (generic concept). "The primary medium" = specific superlative (only one such medium). "Human thought" = zero (abstract generic).','hard'),
  (cid,41,145,'gap_fill','_____ technology has transformed _____ way we communicate, but _____ impact of this transformation on social cohesion remains _____ contested question.','zero / the / the / a',NULL,'Technology (generic) + the way (specific) + the impact (specific established thing) + a contested question (one instance).','hard'),
  (cid,41,146,'multiple_choice','Which sentence uses the ZERO ARTICLE with an ABSTRACT NOUN correctly?','Justice requires that all individuals be treated equally under the law.','["The justice requires that the individuals be treated equally under a law.","Justice requires that all individuals be treated equally under the law.","A justice requires that all individuals be treated equally under law.","Justice requires that all the individuals be treated equally under a law."]','"Justice" = zero (abstract principle). "The law" = specific (the legal system). "Individuals" = countable plural generic = zero.','hard'),

  -- BLOCK 42: Articles em proper nouns (geograficos, institucionais)
  (cid,42,147,'multiple_choice','Which group of proper nouns CORRECTLY uses "the" with the definite article?','The Amazon, the Sahara, the Pacific Ocean, the Eiffel Tower, the United Nations.','["France, Germany, China, Brazil (countries — no article)","The Amazon, the Sahara, the Pacific Ocean, the Eiffel Tower, the United Nations.","Amazon, Sahara, Pacific Ocean, Eiffel Tower, United Nations (all without article — error)","The France, the Germany (countries — error)"]','"The" with rivers (the Amazon), deserts (the Sahara), oceans, famous buildings, international organizations.','medium'),
  (cid,42,148,'gap_fill','_____ Nile flows through _____ Egypt into _____ Mediterranean Sea, making _____ country one of the great riverine civilizations of antiquity.','The / zero / the / the',NULL,'"The Nile" (river) + zero "Egypt" (country) + "the Mediterranean Sea" (sea) + "the country" (specific back-reference).','hard'),
  (cid,42,149,'multiple_choice','Which sentence uses articles with INSTITUTIONS correctly?','She studied at the University of Cambridge and later joined the World Health Organization.','["She studied at University of Cambridge and later joined World Health Organization.","She studied at the University of Cambridge and later joined the World Health Organization.","She studied at an University of Cambridge and later joined a World Health Organization.","She studied at a University of Cambridge and later joined World Health Organization."]','"The University of Cambridge" (specific unique institution). "The World Health Organization" (international org with "the").','medium'),
  (cid,42,150,'gap_fill','_____ United Kingdom consists of _____ England, _____ Scotland, _____ Wales, and _____ Northern Ireland.','The / zero / zero / zero / zero',NULL,'"The United Kingdom" (political union) + zero article for constituent countries (England, Scotland, Wales, NI = no article for constituent parts).','hard'),
  (cid,42,151,'multiple_choice','When are ACADEMIC JOURNALS and BOOKS referenced without "the"?','When cited as titles: "Science published the study" (journal as proper name, no article).','["Always use the with journal titles","When cited as titles: ''Science published the study'' (journal as proper name, no article).","Never use the with journal titles","Academic journals always take a/an"]','Journals and books used as names (Science, Nature, The Lancet) vary: some have "the" as part of the name, most do not.','hard'),

  -- BLOCK 43: Articles em headlines e títulos
  (cid,43,152,'multiple_choice','Why do NEWSPAPER HEADLINES often omit articles?','To save space and create a more telegraphic, impactful style.','["Articles are always omitted in headlines","To save space and create a more telegraphic, impactful style.","Because headlines use past tense","Because articles confuse readers"]','Headline style = telegraphic: articles, auxiliaries, and be-verbs often dropped.','easy'),
  (cid,43,153,'gap_fill','[Headline style → Full sentence] "Government Announces Plan to Reduce Emissions" = _____ government has announced _____ plan to reduce emissions.','The / a',NULL,'"The government" (specific) + "a plan" (one plan, not previously mentioned = indefinite).','medium'),
  (cid,43,154,'gap_fill','[Full sentence → Headline style] "The company reported a significant increase in quarterly profits." = Company Reports Significant Increase in Quarterly _____.','Profits',NULL,'Headline removes "The" and "a"; changes past to present. Profits = plural countable (no article needed with plural general reference in headlines).','medium'),
  (cid,43,155,'multiple_choice','In ACADEMIC PAPER TITLES, which article use is correct?','The Impact of Digital Technology on Educational Outcomes: A Systematic Review.','["Impact of Digital Technology on Educational Outcomes: Systematic Review","The Impact of Digital Technology on Educational Outcomes: A Systematic Review.","An Impact of Digital Technology on Educational Outcomes: A Systematic Review","Impact of the Digital Technology on Educational Outcomes: The Systematic Review"]','"The Impact" (specific study topic). "A Systematic Review" (one instance of this review type, first mention). "Digital Technology" = generic (no article). "Educational Outcomes" = generic (no article).','hard'),

  -- BLOCK 44: Determiners avançados (such a, quite a, rather a, what a)
  (cid,44,156,'gap_fill','This was _____ remarkable finding that it reshaped the entire theoretical framework of the field.','such a',NULL,'"Such a + singular countable adj + noun" = emphatic quality.','medium'),
  (cid,44,157,'gap_fill','The result was _____ significant departure from previous models that the research team _____ (request) an independent audit.','such a / requested',NULL,'"Such a significant departure" = degree + quality emphasis.','medium'),
  (cid,44,158,'multiple_choice','Which sentence correctly uses "such" as a determiner before a noun phrase?','Such an unusual combination of variables had never been studied before.','["Such unusual a combination had never been studied before.","Such an unusual combination of variables had never been studied before.","A such unusual combination had never been studied before.","Such unusual combination of variables had never been studied before."]','"Such + a/an + adj + singular countable noun" = "such an unusual combination."','medium'),
  (cid,44,159,'gap_fill','The conference attracted _____ large audience that additional sessions _____ (need/passive) to accommodate all the registered participants.','such a / were needed',NULL,'"Such a large audience" = degree emphasis. Past passive for result.','medium'),
  (cid,44,160,'gap_fill','The speed of scientific discovery has made this _____ rapidly changing field that traditional textbook content _____ (often/become) obsolete within years of publication.','such a / often becomes',NULL,'"Such a rapidly changing field" + PS for permanent pattern.','hard'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,161,'multiple_choice','[TOEFL Reading] "The Industrial Revolution transformed the relationship between the human being and nature." Which use of "the" is UNUSUAL and requires explanation?','"The human being" (generic singular with "the" to refer to humanity as a collective abstraction).','["The Industrial Revolution — the is used because there was only one","The relationship — specific relationship being discussed","''The human being'' (generic singular with ''the'' to refer to humanity as a collective abstraction).","Nature — no article needed"]','"The human being" = generic singular construction (= humanity). Unusual because generics usually have zero article (humans, people) or plural.','hard'),
  (cid,45,162,'gap_fill','[TOEFL Reading] "_____ climate change presents _____ existential challenge to _____ civilization as we know it." Best articles?','zero / an / zero',NULL,'"Climate change" = generic (zero). "An existential challenge" = one challenge (indefinite). "Civilization" = generic abstract (zero).','hard'),
  (cid,45,163,'multiple_choice','[TOEFL Reading] "The Amazon basin contains approximately 10% of all species currently living on Earth." The definite article "the" is used with "Amazon basin" because:','It is a unique, geographically specific entity.','["Amazon is a river","It is mentioned for the first time","It is a unique, geographically specific entity.","''Basin'' requires ''the''"]','Named geographic features (rivers, deserts, mountain ranges, basins) → "the."','easy'),
  (cid,45,164,'gap_fill','[TOEFL Reading] "_____ rise of _____ nation-state as _____ primary unit of political organization reshaped _____ global order during _____ nineteenth century." Best articles?','The / the / the / the / the',NULL,'"The rise" (specific process), "the nation-state" (specific political form), "the primary unit" (only one), "the global order" (specific established order), "the nineteenth century" (specific century = always "the").','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,165,'production','[TOEFL Speaking — 45s] Discuss the concept of civil society. Use article choices deliberately: generic zero, specific "the," indefinite "a/an."','',NULL,'Civil society refers to the sphere of organized social life that exists independently of both the state and the market — the domain of voluntary associations, community organizations, trade unions, faith communities, and advocacy groups that give citizens a means of collective action beyond formal political participation. The concept has attracted significant scholarly attention because a vibrant civil society is thought to be a precondition for democratic governance: the ability to organize independently, to hold institutions accountable, and to articulate alternative visions of the public good requires the kind of infrastructure that civil society provides. In authoritarian contexts, the state typically seeks to control or suppress civil society, recognizing it as a potential source of opposition. The health of civil society in any given country can be measured in part by the legal protections afforded to freedom of assembly and the degree to which associations can operate without government interference.','hard'),
  (cid,46,166,'production','[TOEFL Speaking — 45s] Explain what the internet has done to the concept of "public sphere." Use articles carefully.','',NULL,'The concept of the public sphere — the arena of open discussion in which citizens debate matters of common concern — was developed by the philosopher Jürgen Habermas to describe the form of reasoned public discourse that emerged in eighteenth-century Europe through newspapers, coffee houses, and salons. The internet initially seemed to realize the promise of the public sphere on a far larger scale: it gave an individual the ability to reach a global audience at virtually no cost, and it created unprecedented space for horizontal communication between citizens rather than top-down communication from institutions to audiences. However, the actual form that online public discourse has taken has led many scholars to question whether the internet represents an enhancement or a degradation of the public sphere. The dominance of a small number of platform companies, the prevalence of misinformation, and the algorithmic amplification of outrage and conflict have made the public sphere more fragmented and emotionally charged rather than more rational and inclusive.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,167,'production','[TOEFL Writing — 150 words] Write a paragraph on the relationship between democracy and economic development. Use articles with deliberate, correct choices throughout.','',NULL,'The relationship between democracy and economic development has long been a subject of debate among political scientists and economists. For much of the twentieth century, a widely held view — associated with arguments about the need for stability and concentrated authority in early stages of development — held that democracy might be a luxury that poor countries could not afford. The authoritarian growth model appeared to have a certain empirical support: Singapore, South Korea, and Taiwan all achieved rapid industrialization under autocratic governments. However, more recent research suggests that the relationship is more complex. Democracy does not appear to be either a precondition for growth or an obstacle to it; instead, the quality of institutions — the rule of law, secure property rights, and protection of contracts — emerges as a more reliable predictor of economic performance than regime type alone.','hard'),
  (cid,47,168,'production','[TOEFL Writing — Error Correction] Fix article errors: "The poverty is serious problem. She did a remarkable research. The government announced a new the policy. An information we need is available online. The nature is complex system."','',NULL,'The poverty → poverty (uncountable generic concept = zero article); a remarkable research → remarkable research (''research'' = uncountable: no a/an); the new the policy → a new policy (one specific policy, not previously mentioned = a; no double article); An information → The information (uncountable: no a/an; use ''the'' if specific); The nature → Nature (generic abstract = zero article).','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,169,'production','[TOEFL Writing — 200 words] Write a paragraph on the role of the state in a market economy. Use articles consistently and deliberately: 5 uses of ''the'', 3 zero article, 3 ''a/an'' uses.','',NULL,'The role of the state in a market economy has been one of the central questions of economic theory and policy for the past two centuries. Classical liberalism — the intellectual tradition associated most strongly with Adam Smith — holds that a free market, left to its own devices, allocates resources more efficiently than any alternative system. In this view, the state should limit its economic role to protecting property rights, enforcing contracts, and providing a narrow range of public goods that the market cannot supply. The Keynesian tradition, which gained influence during the Great Depression of the 1930s, challenged this view by demonstrating that market economies are subject to systematic failures — particularly the tendency to become trapped in equilibria of high unemployment and low demand that spontaneous market adjustment cannot easily escape. In this framework, the state has a legitimate and necessary role as a stabilizer of economic activity and as a provider of public investment in domains such as education, infrastructure, and health, where private markets systematically underinvest.','hard'),
  (cid,48,170,'production','[TOEFL Speaking — 60s] Discuss the concept of cultural identity. Use articles appropriately throughout for both generic and specific reference.','',NULL,'Cultural identity refers to the sense of belonging that an individual derives from membership in a particular cultural group — a community defined by shared language, tradition, history, religion, or some combination of these factors. For most of human history, cultural identity was relatively stable and locally grounded: a person was born into a community, lived within its norms, and died within it, without experiencing the degree of cultural mixing that has become normal in a globalized world. The twentieth century, and more specifically the second half of it, transformed this picture dramatically. Mass migration, mass media, and eventually the internet exposed individuals to a diversity of cultural influences that their ancestors could not have imagined. The result has been what sociologists call the hybridization of identity: individuals navigate multiple cultural frames simultaneously, drawing selectively on different traditions and constructing identities that do not conform neatly to any single cultural category. This is experienced by some as liberation — the freedom to choose rather than inherit — and by others as disorientation or loss.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
